\begin{theorem}[Constructive $0$-Giraud Representation and Banishment of Dogma and Casuistry]\label{ch01:thm:zero-giraud-representation}%
\uses{ch01:def:probe-suite,ch01:prop:topological-no-schism}%
Let $(\mathbb{D}, \times, 0, {{sym:apodictic}})$ be a doctrinal domain equipped with an Alexandrov $S4$ stability interior {{sym:apodictic}} preserving intersections, and let $\Phi = (H, C, K)$ be a doctrinal problem with $T := (\mathbb{D} \setminus H) \cup C$. Constructively without axioms (stratum \textbf{Emerald}):
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item An extent family $\mathcal{M} \subseteq \wp(\mathbb{D})$ arises as arbitrary intersections of an $\iota$-indexed family $P : \iota \to \wp(\mathbb{D})$ of {{sym:j-ext}}-multiplicative, $\Sigma$-invariant, off-core discerning probes if and only if $\mathcal{M}$ satisfies the intrinsic $0$-Giraud axioms:
  \begin{itemize}[leftmargin=1.5em]
    \item \textbf{(P1) $\iota$-Indexed $\bigcap$-Density:} $\mathcal{M}$ is closed under extensional equivalence and arbitrary intersections, and contains a $\bigcap$-dense $\iota$-indexed generator family $(G_i)_{i \in \iota}$;
    \item \textbf{(P3) Multiplicativity:} Every $E \in \mathcal{M}$ contains $0$ and is closed under $\times$;
    \item \textbf{(P4) Modal $\Sigma$-Exactness:} Every $E \in \mathcal{M}$ satisfies ${{sym:apodictic}}(E) = E$;
    \item \textbf{(P5) Off-Core Discernment:} Every $E \in \mathcal{M}$ satisfies ${{sym:apodictic}}((\mathbb{D} \setminus H) \cup K) \subseteq E \implies E = \top$ (hence $E \neq \top \implies {{sym:apodictic}}((\mathbb{D} \setminus H) \cup K) \not\subseteq E$).
  \end{itemize}
  \item If $\Phi$ is non-trivial ($\exists w \in H \setminus C$), axiom~\textbf{(P5)} simultaneously banishes \textbf{Dogma} ($T \notin \mathcal{M}$) and \textbf{Immortal Casuistry} (${{sym:apodictic}}(T) \notin \mathcal{M}$).
\end{enumerate}
\end{theorem}
\begin{proof}
For~(1), if $\mathcal{M}$ is generated by intersections $\bigcap_{i \in S} P_i$ of an admissible probe family $(P_i)_{i \in \iota}$, taking $G_i := P_i$ yields $\bigcap$-density (P1), while multiplicativity (P3), Alexandrov intersection preservation for (P4), and pointwise intersection pass-through for (P5) transfer from each $P_i$ to every $E \in \mathcal{M}$. Conversely, (P1) supplies generators $G_i \in \mathcal{M}$, and axioms (P3)--(P5) on $\mathcal{M}$ immediately certify that $(G_i)_{i \in \iota}$ is an admissible probe family generating $\mathcal{M}$. For~(2), since $K \subseteq C$, $(\mathbb{D} \setminus H) \cup K \subseteq T$, whence ${{sym:apodictic}}((\mathbb{D} \setminus H) \cup K) \subseteq {{sym:apodictic}}(T) \subseteq T$; thus if either $T \in \mathcal{M}$ or ${{sym:apodictic}}(T) \in \mathcal{M}$, (P5) forces $w \in T$ (contradicting $w \in H \setminus C$).
\end{proof}

\begin{theorem}[$0$-Giraud Living-Zone Existence via Zorn's Lemma]\label{ch01:thm:zero-giraud-living-zone-zorn}%
\uses{ch01:prop:topological-no-schism,ch01:thm:zero-giraud-representation}%
Let $\mathcal{M} \subseteq \wp(\mathbb{D})$ be closed under arbitrary intersections (in particular satisfying~\textbf{(P1)} of Theorem~\ref{ch01:thm:zero-giraud-representation}). Assume additionally:
\begin{itemize}[leftmargin=1.5em]
  \item \textbf{(P0) Core--Target Aperture:} $c_{\mathcal{M}}(K) \subseteq T$, where $c_{\mathcal{M}}(U) := \bigcap\{E \in \mathcal{M} \mid U \subseteq E\}$;
  \item \textbf{(P2) Directed Union Closure:} $\mathcal{M}$ is closed under unions $\bigcup \mathcal{C}$ of nonempty directed subfamilies $\mathcal{C} \subseteq \mathcal{M}$.
\end{itemize}
Then the Living-Zone poset $\mathcal{F} = \{R \in \mathcal{M} \mid K \subseteq R \subseteq T\}$ possesses at least one inclusion-maximal Pareto residuum extent $R \in \mathrm{Max}(\mathcal{F})$ above $c_{\mathcal{M}}(K)$. (Stratum \textbf{Crimson}, isolating \texttt{Classical.choice} strictly to Zorn maximization.)
\end{theorem}
\begin{proof}
By intersection closure and~\textbf{(P0)}, $x_0 := c_{\mathcal{M}}(K)$ satisfies $x_0 \in \mathcal{M}$ and $K \subseteq x_0 \subseteq T$, so $x_0 \in \mathcal{F}$. For any nonempty chain $\mathcal{C} \subseteq \mathcal{F}$, total comparability makes $\mathcal{C}$ directed, whence~\textbf{(P2)} places $\bigcup \mathcal{C} \in \mathcal{M}$; moreover $K \subseteq E_0 \subseteq \bigcup \mathcal{C} \subseteq T$ for any $E_0 \in \mathcal{C}$, so $\bigcup \mathcal{C} \in \mathcal{F}$ upper-bounds $\mathcal{C}$. Applying Zorn's Lemma (\texttt{zorn\_subset\_nonempty}) above $x_0$ produces an inclusion-maximal Living-Zone extent $R \in \mathrm{Max}(\mathcal{F})$.
\end{proof}

\begin{counterexample}[Independence of Core--Target Aperture \textup{(P0)} from \textup{(P1)--(P5)}]\label{ch01:cex:p0-independent-of-p1-p5}%
\uses{ch01:thm:zero-giraud-representation,ch01:thm:zero-giraud-living-zone-zorn}%
Let $D = \mathbf{Fin}\,4 = \{0 < k < w < h\}$ ($0 \mapsto 0, 1 \mapsto k, 2 \mapsto w, 3 \mapsto h$) carry the join-semilattice multiplication $\mathrm{mul} := \max$, unit $0$, and trivial interior ${{sym:apodictic}} := \mathrm{id}$. Set $H = \{0, 1, 2\}$, $C = K = \{0, 1\}$ (whence $T = (D \setminus H) \cup C = \{0, 1, 3\}$ and defect $w = 2$), and take $\mathcal{M} := \{D, \{0, 1, 2\}\}$ generated by the single probe $P_\bullet = \{0, 1, 2\}$. Constructively without axioms (stratum \textbf{Emerald}):
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item $\mathcal{M}$ satisfies~\textbf{(P1)} ($\bigcap$-density), constructive~\textbf{(P2)} (closed under nonempty directed unions on finite Boolean chains and decidable unions), \textbf{(P3)} ($0 \in P_\bullet$ and $\max$-closure), \textbf{(P4)} ($\mathrm{id}(E) = E$), and~\textbf{(P5)} (since $(D \setminus H) \cup K = \{0, 1, 3\} \not\subseteq \{0, 1, 2\}$).
  \item However, $c_{\mathcal{M}}(K) = \{0, 1, 2\} \not\subseteq \{0, 1, 3\} = T$, so~\textbf{(P0)} fails ($w = 2 \in c_{\mathcal{M}}(K) \setminus T$) and the Living-Zone poset $\mathcal{F} = \emptyset$ is empty.
\end{enumerate}
\end{counterexample}
\begin{proof}
Because $P_\bullet = \{0, 1, 2\}$ is a lower set of $D = \mathbf{Fin}\,4$ containing $0$, it is $\max$-closed~\textbf{(P3)} and $\mathrm{id}$-invariant~\textbf{(P4)}; because $h = 3 \in (D \setminus H) \cup K$ lies outside $P_\bullet$, $P_\bullet$ satisfies~\textbf{(P5)}. Theorem~\ref{ch01:thm:zero-giraud-representation} therefore certifies~\textbf{(P1)}, \textbf{(P3)}, \textbf{(P4)}, and~\textbf{(P5)} for $\mathcal{M} = \{D, \{0,1,2\}\}$, while direct Boolean evaluation proves directed union closure~\textbf{(P2)}. Yet every extent in $\mathcal{M}$ covering $K = \{0,1\}$ also contains $w = 2 \notin T$, violating~\textbf{(P0)} and forcing $\mathcal{F} = \emptyset$.
\end{proof}

\begin{theorem}[Two-Sided Quasi-Isometric Morita Resource Interleaving]\label{ch01:thm:morita-resource-interleaving}%
\uses{ch01:def:operational-currencies,ch01:claim:abramsky-arboreal-coalgebra-numbers}%
Let $(I, J; \eta, \varepsilon)$ be a syntactic pretopos bi-interpretation between first-order theories $T_1$ and $T_2$~\cite{johnstone2002} whose induced quotient/finite-product definitions have forward quantifier-rank distortion $(a, b) \in \mathbb{N}_{\ge 1} \times \mathbb{N}$ and backward distortion $(a', b') \in \mathbb{N}_{\ge 1} \times \mathbb{N}$ relative to the Ehrenfeucht--Fra\"iss\'e game-comonad towers {{sym:ef-comonad}} of {{ref:ch01:claim:abramsky-arboreal-coalgebra-numbers}}. Then for all $k, m \in \mathbb{N}$:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Two-Sided Interleaving:}
  \[
    (\equiv_{a k + b}^{\mathbb{E}, T_1}) \;\subseteq\; I^*(\equiv_k^{\mathbb{E}, T_2}), \qquad
    I^*(\equiv_{a' m + b'}^{\mathbb{E}, T_2}) \;\subseteq\; (\equiv_m^{\mathbb{E}, T_1}).
  \]
  \item \textbf{Floor-Bound Corollary:} For every $k \ge b'$, $I^*(\equiv_k^{\mathbb{E}, T_2}) \subseteq (\equiv_{\lfloor (k - b')/a' \rfloor}^{\mathbb{E}, T_1})$.
  \item \textbf{Exact $k = \infty$ Invariance:} $\bigcap_{k \in \mathbb{N}} \equiv_k^{\mathbb{E}, T_1} \;=\; I^*\!\Bigl(\bigcap_{k \in \mathbb{N}} \equiv_k^{\mathbb{E}, T_2}\Bigr)$.
\end{enumerate}
\end{theorem}
\begin{proof}
Each definable sort and relation of $T_2$ translates along $I$ into finite tuples and formulas over $T_1$ of bounded quantifier-rank overhead $(a, b)$, so any Spoiler $k$-round strategy between $I(M_1)$ and $I(M_2)$ unfolds to an $(ak + b)$-round Spoiler strategy between $M_1$ and $M_2$; contrapositively, $M_1 \equiv_{ak+b}^{\mathbb{E}, T_1} M_2 \implies I(M_1) \equiv_k^{\mathbb{E}, T_2} I(M_2)$. Symmetrically, translating along $J$ with backward distortion $(a', b')$ gives $I(M_1) \equiv_{a'm+b'}^{\mathbb{E}, T_2} I(M_2) \implies J(I(M_1)) \equiv_m^{\mathbb{E}, T_1} J(I(M_2))$, and the unit isomorphism $\eta_{M} : M \cong J(I(M))$ transfers this to $M_1 \equiv_m^{\mathbb{E}, T_1} M_2$. For $k \ge b'$, setting $m := \lfloor (k - b')/a' \rfloor$ yields $a' m + b' \le k$, so antitonicity of the descending filtration gives $I^*(\equiv_k^{\mathbb{E}, T_2}) \subseteq I^*(\equiv_{a' m + b'}^{\mathbb{E}, T_2}) \subseteq (\equiv_m^{\mathbb{E}, T_1})$. Taking the intersection over all $k \in \mathbb{N}$ yields exact $k = \infty$ Morita invariance~\cite{abramsky2022,abramsky_shah2021}.
\end{proof}

\begin{counterexample}[Russell's Socks Touchstone: Levelwise Morita Failure]\label{ch01:cex:russells-socks-levelwise-morita-failure}%
\uses{ch01:thm:morita-resource-interleaving}%
Consider the single-sorted theory $T_1$ of paired socks $(X, E, D)$ (pair equivalence $E$, irreflexive symmetric mismatch relation $D \subseteq E \setminus \Delta_X$) and its Morita-equivalent quotient presentation $T_2$ adjoining the pair sort $Q = X/E$, projection graph $G_\pi(x, q)$, and definable predicate $\mathrm{Mis}(q) \iff \exists x, y,\; G_\pi(x,q) \wedge G_\pi(y,q) \wedge D(x,y)$. Constructively without axioms (stratum \textbf{Emerald}):
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item The explicit interpretation functor $I : \mathbf{Mod}(T_1) \xrightarrow{\sim} \mathbf{Mod}(T_2)$ has exact inverse $J$ ($J(I(M)) = M$).
  \item On the two-sock models $M_{\mathrm{match}}$ ($D = \emptyset$) and $M_{\mathrm{mis}}$ (one mismatched pair), $M_{\mathrm{match}} {{sym:ef-equiv}} M_{\mathrm{mis}}$ holds at $k = 1$ in $T_1$.
  \item Inside $T_2$, however, $I(M_{\mathrm{match}}) \not\equiv_1^{\mathbb{E}} I(M_{\mathrm{mis}})$ fails already at $k = 1$.
  \item Two rounds suffice to restore separation in $T_1$: $M_{\mathrm{match}} \not\equiv_2^{\mathbb{E}} M_{\mathrm{mis}}$.
\end{enumerate}
\end{counterexample}
\begin{proof}
At $k = 1$ in $T_1$, Spoiler picks a single sock $x$, Duplicator replies with the corresponding sock, and no $2$-element subset can witness $D$ (since $D$ is irreflexive), so all $1$-element partial isomorphisms agree. Under $I$, the quotient predicate $\mathrm{Mis}(q)$ reduces a $2$-quantifier property over $X$ to a $1$-quantifier unary property on $Q$, so Spoiler picks the unique pair element $q \in Q$ at $k = 1$ and separates $\mathrm{Mis}(q) = \mathrm{false}$ from $\mathrm{Mis}(q) = \mathrm{true}$. Thus levelwise preservation ($a=1, b=0$) fails, whereas $k=2 = 1 \cdot 1 + 1$ in $T_1$ separates $M_{\mathrm{match}}$ from $M_{\mathrm{mis}}$, exemplifying the additive shift $b = 1$ of Theorem~\ref{ch01:thm:morita-resource-interleaving}.
\end{proof}

